public int[] findOrder(int numCourses, int[][] prerequisites) {
    List<List<Integer>> adj = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) {
        adj.add(new ArrayList<>());
    }
    int[] indegree = new int[numCourses];
    for (int[] p : prerequisites) {
        adj.get(p[1]).add(p[0]); // edge: prerequisite -> course
        indegree[p[0]]++;
    }
    Queue<Integer> queue = new LinkedList<>();
    for (int i = 0; i < numCourses; i++) {
        if (indegree[i] == 0) {
            queue.offer(i);
        }
    }
    int[] order = new int[numCourses];
    int idx = 0;
    while (!queue.isEmpty()) {
        int course = queue.poll();
        order[idx++] = course;
        for (int next : adj.get(course)) {
            if (--indegree[next] == 0) {
                queue.offer(next);
            }
        }
    }
    return idx == numCourses ? order : new int[]{};
}

private List<List<Integer>> adj;
private int[] state; // 0=white, 1=grey, 2=black
private List<Integer> order;
private boolean hasCycle;

public int[] findOrder(int numCourses, int[][] prerequisites) {
    adj = new ArrayList<>();
    for (int i = 0; i < numCourses; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] p : prerequisites) {
        adj.get(p[1]).add(p[0]);
    }
    state = new int[numCourses];
    order = new ArrayList<>();
    hasCycle = false;
    for (int i = 0; i < numCourses; i++) {
        if (state[i] == 0) {
            dfs(i);
        }
    }
    if (hasCycle) {
        return new int[]{};
    }
    Collections.reverse(order);
    int[] result = new int[numCourses];
    for (int i = 0; i < numCourses; i++) {
        result[i] = order.get(i);
    }
    return result;
}

private void dfs(int node) {
    state[node] = 1; // grey: on the current path
    for (int next : adj.get(node)) {
        if (state[next] == 1) {
            hasCycle = true;
            return;
        }
        if (state[next] == 0) {
            dfs(next);
            if (hasCycle) {
                return;
            }
        }
    }
    state[node] = 2; // black: fully explored
    order.add(node); // post-order
}

